package target

import "bytes"

// Marker identifies generated files; the edit guard and orphan detection look
// for it in a file's first lines.
const Marker = "Code generated by claude-gen; DO NOT EDIT."

// WithMarker adds Marker to body: as a YAML comment on the line after an
// opening --- (frontmatter must stay on line 1), else as an HTML comment on
// line 1.
func WithMarker(body []byte) []byte {
	if bytes.HasPrefix(body, []byte("---\n")) {
		out := make([]byte, 0, len(body)+len(Marker)+4)
		out = append(out, "---\n# "+Marker+"\n"...)
		return append(out, body[len("---\n"):]...)
	}
	out := make([]byte, 0, len(body)+len(Marker)+10)
	out = append(out, "<!-- "+Marker+" -->\n"...)
	return append(out, body...)
}
